html:
{%- set company = frappe.db.get_value("Company", doc.company, ["company_name", "registration_details", "offer_logo", "offer_stamp", "offer_header_text"], as_dict=True) or {} -%}
{%- set product_image = frappe.db.get_value("Item", doc.main_item, "image") -%}
{%- set base = frappe.utils.get_url() -%}
{%- set title = doc.pdf_title or doc.item_name -%}
{%- set currency_label = "грн" if doc.currency == "UAH" else doc.currency -%}
{%- set price_text = ("{:,.2f}".format(doc.price or 0)).replace(",", " ").replace(".", ",") -%}
{%- set price_short = price_text[:-3] if price_text.endswith(",00") else price_text -%}
{%- set key_rows = doc.spec_fields | selectattr("section", "equalto", "Key Capability") | list -%}
{%- set spec_rows = doc.spec_fields | selectattr("section", "equalto", "Specification") | list -%}
{%- set spec_pages = spec_rows | batch(24) | list -%}
{%- set total_pages = 1 + (spec_pages | length) -%}
{%- macro cell_value(row) -%}{{ (row.preview or "") | e }}{% if row.unit and row.preview %} {{ row.unit | e }}{% endif %}{%- endmacro -%}
{%- macro page_header(title, cover=False) -%}
<table class="hdr"><tr>
	<td class="hdr-logo">{% if company.offer_logo %}<img src="{{ company.offer_logo }}" />{% endif %}</td>
	{% if cover %}<td class="hdr-cover">{{ _("Commercial Offer") }}</td>{% else %}<td class="hdr-text">{{ (company.offer_header_text or "") | e | replace("
", "<br>") }}</td>{% endif %}
</tr></table>
{% if title %}<div class="chip">{{ title }}</div>{% endif %}
{%- endmacro -%}
{%- macro page_footer(n, left) -%}
<table class="ftr"><tr>
	<td class="ftr-left">{{ left | e }}</td>
	<td class="ftr-right">{{ _("Page {0} of {1}").format(n, total_pages) }}</td>
</tr></table>
{%- endmacro -%}
<link rel="stylesheet" href="/assets/frappe/css/fonts/fontawesome/font-awesome.min.css">
<style>
	.print-format { margin-top: 0mm; margin-bottom: 0mm; margin-left: 0mm; margin-right: 0mm; padding: 0 !important; max-width: none !important; }
	body { margin: 0 !important; }
	.print-format-gutter { padding: 0 !important; background: none !important; }
	@font-face { font-family: Inter; font-weight: 400; src: url("{{ base }}/assets/erpnext/fonts/inter/Inter-Regular.ttf") format("truetype"); }
	@font-face { font-family: Inter; font-weight: 600; src: url("{{ base }}/assets/erpnext/fonts/inter/Inter-SemiBold.ttf") format("truetype"); }
	@font-face { font-family: Inter; font-weight: 700; src: url("{{ base }}/assets/erpnext/fonts/inter/Inter-Bold.ttf") format("truetype"); }
	.co { font-family: Inter, "DejaVu Sans", Arial, sans-serif; color: #1a1d24; font-size: 13px; line-height: 1.4; }
	.co * { box-sizing: border-box; }
	.co .page { width: 210mm; height: 296mm; position: relative; overflow: hidden; page-break-after: always; background: #fff; }
	.co .page.last { page-break-after: auto; }
	.co .fa { font-family: FontAwesome !important; font-style: normal; font-weight: normal; display: inline-block; line-height: 1; padding: 0 3px; overflow: visible; }
	.co .caps .ic .fa, .co .tiles .ic .fa { color: #777 !important; }
	.co .fa:before { color: inherit !important; }
	.co .tiles td.dark .ic .fa { color: #c9ccd3 !important; }
	.co table { border-collapse: collapse; }
	.co .hdr { width: 100%; margin: 0; }
	.co .hdr td { vertical-align: middle; }
	.co .hdr-logo { padding: 8mm 0 0 8mm; width: 90mm; }
	.co .hdr-logo img { width: 62mm; height: auto; max-height: 22mm; }
	.co .hdr-text { padding: 8mm 8mm 0 0; text-align: right; font-size: 11px; line-height: 1.5; }
	.co .hdr-cover { padding: 8mm 8mm 0 8mm; width: 100mm; border-left: 1px solid #ddd; font-size: 17px; text-transform: uppercase; color: #3b3f2e; }
	.co .hdr-logo { width: 100mm; }
	.co .chip { display: inline-block; margin: 6mm 0 0 8mm; padding: 2.5mm 5mm; background: #9a8a6b; color: #fff; font-size: 15px; white-space: nowrap; text-transform: uppercase; border-radius: 3mm; }
	.co .title { margin: 4mm 8mm 0 8mm; font-size: 20px; font-weight: 700; text-transform: uppercase; }
	.co .ftr { position: absolute; left: 8mm; right: 8mm; bottom: 8mm; width: 194mm; background: #f6f6f4; border-top: 1px solid #e8e8e4; }
	.co .ftr td { padding: 5mm 8mm; font-size: 12px; font-weight: 600; }
	.co .ftr-right { text-align: right; font-weight: 400 !important; }
	.co .grid { margin: 6mm 8mm 0 8mm; width: 194mm; border: 1px solid #e0e0dc; }
	.co .grid th { background: #1a1d24; color: #fff; text-align: left; padding: 3.5mm 3mm !important; font-size: 13px; }
	.co .grid td { padding: 1.9mm 3mm !important; height: auto !important; border-top: 1px solid #ececea; vertical-align: middle; }
	.co .grid tr.odd td { background: #f6f6f4; }
	.co .grid .num { width: 11mm; color: #777; }
	.co .grid .val { width: 62mm; }
	.co .grid .sub td { color: #666; }
	.co .grid .group td { font-weight: 700; }
	.co .band { margin: 0 8mm; width: 194mm; background: #f6f6f4; border-top: 1px solid #e8e8e4; border-bottom: 1px solid #e8e8e4; }
	.co .hero { margin-top: 8mm; }
	.co .hero td { vertical-align: middle; padding: 6mm 8mm; }
	.co .hero .kind { max-width: 75mm; font-size: 22px; line-height: 1.25; text-transform: uppercase; }
	.co .hero .name { display: inline-block; margin: 2mm 0 4mm -8mm; padding: 1.5mm 5mm 1.5mm 8mm; background: #9a8a6b; color: #fff; font-size: 19px; white-space: nowrap; font-weight: 700; text-transform: uppercase; border-radius: 0 3mm 3mm 0; }
	.co .hero .tag { font-size: 12px; white-space: pre-line; }
	.co .hero .made { margin-top: 6mm; font-size: 11px; color: #666; }
	.co .hero .made svg { vertical-align: middle; margin-right: 6px; }
	.co .hero .made span { vertical-align: middle; color: #666; }
	.co .hero img { max-width: 96mm; max-height: 70mm; }
	.co .h2 { margin: 11mm 8mm 5mm 8mm; font-size: 17px; text-transform: uppercase; }
	.co .caps { width: 194mm; margin: 0 8mm; }
	.co .caps td { text-align: center; vertical-align: top; padding: 0 2mm; }
	.co .caps .ic { font-size: 30px; color: #777 !important; height: 14mm; }
	.co .caps .v { font-size: 17px; font-weight: 700; }
	.co .caps .u { font-size: 12px; font-weight: 400; color: #555; }
	.co .caps .l { margin-top: 2mm; font-size: 10px; color: #555; }
	.co .tiles { width: 194mm; margin: 0 8mm; border-collapse: separate; border-spacing: 3mm 0; margin-left: 5mm; }
	.co .tiles td { width: 25%; text-align: center; vertical-align: top; padding: 11mm 3mm; background: #f6f6f4; border: 1px solid #e8e8e4; border-radius: 4mm; }
	.co .tiles td.dark { background: #1a1d24; color: #fff; border-color: #1a1d24; }
	.co .tiles td.dark .v { color: #fff !important; }
	.co .tiles td.dark .ic { color: #bbb !important; }
	.co .tiles .ic { font-size: 30px; color: #777; height: 14mm; }
	.co .tiles .v { font-size: 18px; font-weight: 700; }
	.co .tiles .v small { font-size: 11px; font-weight: 400; color: #777; }
	.co .tiles .l { margin-top: 2mm; font-size: 11px; color: #666; }
	.co .tiles .dark .l { color: #ddd; }
	.co .cls { margin: 16mm 8mm 0 8mm; width: 194mm; background: #f6f6f4; padding: 6mm 8mm; border-top: 1px solid #e8e8e4; }
	.co .legal { margin: 14mm 8mm 0 8mm; font-size: 14px; line-height: 1.5; }
	.co .legal h4 { margin: 6mm 0 1mm 0; font-size: 14px; font-weight: 700; }
	.co .legal p { margin: 0; }
	.co .sign { margin: 22mm 8mm 0 8mm; width: 194mm; }
	.co .sign td { vertical-align: top; padding: 0 !important; }
	.co .sign img { max-height: 40mm; max-width: 60mm; }
</style>
<div class="co">

<div class="page">
	{{ page_header("", True) }}
	<table class="band hero"><tr>
		<td style="width: 100mm;">
			<div class="kind">{{ (doc.product_type or "") | e }}</div>
			<div class="name">{{ title | e }}</div>
			<div class="tag">{{ (doc.tagline or "") | e }}</div>
			<div class="made"><svg class="tryzub" width="13" height="18" viewBox="0 0 13 18" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M6.50231 0C6.52092 0.0106545 6.53643 0.0288632 6.55126 0.0453873C7.31354 0.894418 7.90318 1.92809 8.13683 3.06155C8.23987 3.57348 8.28281 4.09626 8.26474 4.6187C8.25328 4.96311 8.2139 5.35333 8.1916 5.70251C8.15865 6.22471 8.13176 6.74728 8.11095 7.27013C8.03744 8.91216 7.9855 10.5551 7.95516 12.1985H10.4555C10.3927 11.654 10.3163 11.1161 10.2617 10.5644C9.99758 7.89665 9.85097 4.37032 12.2968 2.66953C12.5208 2.51381 12.7602 2.39495 13 2.27125L12.9997 15.0879L8.1212 15.0873C8.06992 15.268 7.95068 15.5637 7.87635 15.7369C7.52861 16.5566 7.06519 17.3191 6.50101 18C6.48037 17.9523 6.32556 17.7614 6.28552 17.7092C6.19164 17.5867 6.10063 17.462 6.01259 17.3349C5.66035 16.8199 5.36067 16.269 5.11825 15.6909C5.04279 15.5136 4.94022 15.2614 4.88257 15.0758L0.00614906 15.0779L0.00622514 6.61992C0.00620567 5.17709 -0.00987791 3.70161 0.0097362 2.26243C0.694143 2.6059 1.25085 2.98418 1.7155 3.62021C3.40314 5.93035 2.87953 9.5386 2.54946 12.1872L5.07109 12.1874C5.07297 11.9428 5.06054 11.6882 5.05435 11.4423L5.01797 10.0552C4.97854 8.30509 4.89662 6.55629 4.77229 4.8104C4.66728 3.2619 5.07703 1.90513 5.97417 0.661095C6.14385 0.425813 6.31581 0.220415 6.50231 0Z" fill="#90836A"/></svg><span>{{ _("Made in Ukraine") }}</span></div>
		</td>
		<td style="text-align: center;">{% if product_image %}<img src="{{ product_image }}" />{% endif %}</td>
	</tr></table>
	{% if key_rows %}
	<div class="h2">{{ _("Key Capabilities") }}</div>
	<table class="caps"><tr>
		{% for row in key_rows[:5] %}
		<td style="width: {{ (100 / ([key_rows | length, 5] | min)) | round(1) }}%;">
			<div class="ic"><i class="fa {{ row.icon or 'fa-circle-o' }}" style="color: #777 !important;"></i></div>
			<div class="v">{{ (row.preview or "") | e }} <span class="u">{{ (row.unit or "") | e }}</span></div>
			<div class="l">{{ row.label | e }}</div>
		</td>
		{% endfor %}
	</tr></table>
	{% endif %}
	<div class="h2" style="margin-top: 10mm;">{{ _("Commercial Terms") }}</div>
	<table class="tiles"><tr>
		<td><div class="ic"><i class="fa fa-cube" style="color: #777 !important;"></i></div><div class="v">{{ doc.qty }}</div><div class="l">{{ _("pcs") }}</div></td>
		<td><div class="ic"><i class="fa fa-calendar-o" style="color: #777 !important;"></i></div><div class="v">{{ doc.delivery_days }} <small>{{ _("days") }}</small></div><div class="l">{{ _("delivery term") }}</div></td>
		<td><div class="ic"><i class="fa fa-clock-o" style="color: #777 !important;"></i></div><div class="v">{{ doc.valid_days }} <small>{{ _("days") }}</small></div><div class="l">{{ _("offer validity") }}</div></td>
		<td class="dark"><div class="ic"><i class="fa fa-money" style="color: #c9ccd3 !important;"></i></div><div class="v">{{ price_short }} {{ currency_label }}</div><div class="l">{{ _("total price* without VAT") }}</div></td>
	</tr></table>
	{% if doc.classification_text %}
	<table class="cls"><tr><td>
		<div class="h2" style="margin: 0 0 2mm 0; font-size: 15px;">{{ _("Classification Data") }}</div>
		<div style="white-space: pre-line;">{{ doc.classification_text | e }}</div>
	</td></tr></table>
	{% endif %}
	{{ page_footer(1, title) }}
</div>

{%- set ns = namespace(n=0, page=1) -%}
{% for rows in spec_pages %}
{%- set ns.page = ns.page + 1 -%}
<div class="page{{ ' last' if loop.last }}">
	{% if loop.first %}<div class="title" style="margin-top: 14mm;">«{{ title | e }}»</div>{% endif %}
	<table class="grid">
		<thead><tr><th class="num">№</th><th>{{ _("Parameter") }}</th><th class="val">{{ _("Value, unit") }}</th></tr></thead>
		<tbody>
		{% for row in rows %}
			{%- set is_sub = (row.label or "").startswith("-") -%}
			{%- if not is_sub %}{% set ns.n = ns.n + 1 %}{% endif -%}
			<tr class="{{ 'odd' if loop.index is odd }} {{ 'sub' if is_sub }} {{ 'group' if (not is_sub and not row.preview) }}">
				<td class="num">{{ '' if is_sub else ns.n }}</td>
				<td>{{ row.label | e }}</td>
				<td class="val">{{ cell_value(row) }}</td>
			</tr>
		{% endfor %}
		</tbody>
	</table>
</div>
{% endfor %}

</div>
